policy.text:
// kamanu H4: the request-sum cap at 1m, one action (Bank Pay), cap 100.

@id("pay_cap")
permit (
    principal,
    action == Bank::Action::"Pay",
    resource
)
when temporal {
    (sum a for (a: Long), (t: Timepoint). where (
        formerly within 1m (Bank::Action::"Pay"::request{ input.amount: a } && tp(t))
    )) <= 100
};
